// The active sheet's pools as last read from the store, and what they work out to: each member's cut, and each
// person's cut total.
@Injectable({ providedIn: 'root' })
export class PoolStore {
  private readonly roster = inject(PoolRoster);
  private readonly settings = inject(SettingsStore);
  private readonly session = inject(Session);
  private readonly crews = inject(CrewRoster);

  readonly pools = signal<readonly PoolView[]>([]);
  // The stored pools, then each crew as a pool, in the order the crews were added.
  readonly all = computed(() => {
    const names = new Map(this.roster.people().map((p) => [p.id, p.name]));
    return [...this.pools(), ...this.crews.crews().map((c) => crewPool(c, names))];
  });
  // Every name a pool or a crew goes by: a pool cannot take a crew's name, nor a crew a pool's.
  readonly names = computed(() => new Set(this.all().map((p) => p.name)));
  // The pools with each member counted retired as the people list has them now, the totals to match, and each
  // member's cut of the pool's pot while the pool is balanced (see shownPools).
  readonly shown = computed(() =>
    shownPools(this.all(), this.roster.people(), this.settings.pot(), this.session.sheetToday()),
  );

  // The pools as they stood for each closed or soft-closed period, and at the end of each other period whose to-date
  // is on or before the sheet's today, as last read from the store.
  readonly history = signal<readonly PeriodPools[]>([]);
  // For each such period, by name, each member's cut as it stood (fixed at its close, else at the end of it), by pool
  // id then member key ('' for none). An open period ending on the sheet's today stands as the sheet does now.
  readonly cutHistory = computed(() => {
    const today = this.session.sheetToday();
    const result: { period: string; cuts: Map<number, Map<string, string>> }[] = [];
    for (const h of this.history()) {
      if (!h.fixed && today !== null && h.day > today) continue;
      let shown: readonly ShownPool[];
      if (!h.fixed && h.day === today) {
        shown = this.shown();
      } else {
        const names = new Map(h.people.map((p) => [p.id, p.name]));
        const all = [...h.pools, ...h.crews.map((c) => crewPool(c, names))];
        shown = shownPools(all, h.people, h.pot, h.day);
      }
      result.push({
        period: h.period,
        cuts: new Map(shown.map((p) => [p.id, new Map(p.members.map((m) => [m.key, m.cut]))])),
      });
    }
    return result;
  });

  // Each person's cut total (their cuts across every pool they are a member of, a pool showing no cuts adding
  // nothing), by person id; a person in no pool with a cut is absent.
  readonly cutTotals = computed(() => {
    const totals = new Map<number, string>();
    const sums = new Map<number, bigint>();
    for (const pool of this.shown())
      for (const m of pool.members)
        if (m.personId !== null && m.cut !== '') sums.set(m.personId, (sums.get(m.personId) ?? 0n) + cents(m.cut));
    for (const [id, c] of sums) totals.set(id, money(c));
    return totals;
  });

  // The sheet's cut total: everyone's cut totals added up.
  readonly cutTotal = computed(() => {
    let sum = 0n;
    for (const t of this.cutTotals().values()) sum += cents(t);
    return money(sum);
  });
}

